package com.amar.slackclone.attachment;import org.springframework.beans.factory.annotation.Value;import org.springframework.core.io.*;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;import java.nio.file.*;import java.io.*;import java.util.*;
@Service public class FileStorageService{private final Path root;private static final Set<String> ALLOWED=Set.of("image/jpeg","image/png","image/gif","image/webp","application/pdf","text/plain","text/csv","application/vnd.openxmlformats-officedocument.wordprocessingml.document","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");private static final Set<String> AVATAR_TYPES=Set.of("image/jpeg","image/png","image/webp");public FileStorageService(@Value("${app.upload.directory:uploads}")String dir)throws IOException{root=Paths.get(dir).toAbsolutePath().normalize();Files.createDirectories(root);Files.createDirectories(root.resolve("avatars"));}public String store(MultipartFile f)throws IOException{if(f.isEmpty()||f.getSize()>10*1024*1024)throw new IllegalArgumentException("File must be between 1 byte and 10 MB");if(!ALLOWED.contains(f.getContentType()))throw new IllegalArgumentException("File type is not allowed");String key=UUID.randomUUID().toString();Path target=root.resolve(key).normalize();if(!target.getParent().equals(root))throw new IllegalArgumentException("Invalid storage path");try(InputStream in=f.getInputStream()){Files.copy(in,target,StandardCopyOption.REPLACE_EXISTING);}return key;}public String storeAvatar(MultipartFile f)throws IOException{if(f.isEmpty()||f.getSize()>5*1024*1024)throw new IllegalArgumentException("Avatar must be between 1 byte and 5 MB");if(!AVATAR_TYPES.contains(f.getContentType()))throw new IllegalArgumentException("Avatar must be JPG, PNG, or WEBP");byte[] bytes=f.getBytes();if(!matchesImageSignature(bytes,f.getContentType()))throw new IllegalArgumentException("Avatar content does not match its image type");String key=UUID.randomUUID().toString();Path target=avatarPath(key);Files.write(target,bytes,StandardOpenOption.CREATE_NEW);return key;}public Resource loadAvatar(String key){return new FileSystemResource(avatarPath(key));}public void deleteAvatar(String key)throws IOException{if(key!=null)Files.deleteIfExists(avatarPath(key));}private Path avatarPath(String key){if(key==null||!key.matches("[0-9a-fA-F-]{36}"))throw new IllegalArgumentException("Invalid avatar key");Path dir=root.resolve("avatars").normalize();Path p=dir.resolve(key).normalize();if(!p.getParent().equals(dir))throw new IllegalArgumentException("Invalid storage path");return p;}private boolean matchesImageSignature(byte[] b,String type){if(type.equals("image/jpeg"))return b.length>2&&(b[0]&255)==0xff&&(b[1]&255)==0xd8&&(b[2]&255)==0xff;if(type.equals("image/png"))return b.length>7&&(b[0]&255)==0x89&&b[1]==0x50&&b[2]==0x4e&&b[3]==0x47;if(type.equals("image/webp"))return b.length>11&&new String(b,0,4).equals("RIFF")&&new String(b,8,4).equals("WEBP");return false;}public Resource load(String key){Path p=root.resolve(key).normalize();if(!p.getParent().equals(root))throw new IllegalArgumentException("Invalid storage path");return new FileSystemResource(p);}}
